INSERT OR REPLACE INTO "char_abilities" VALUES(1795000101,3,2031001,'超强势EX LV1','[{"tid":203100100,"trait_id":203100101,"trait":{"id":203100101,"trait_type":13,"trait_value":203100107,"desc":"搭乘单位含有「GUNDAM EXA」系列，且自身战意为「超强势」以上时，\n「支援攻击／反击」+1次(1回合)、\n自身射击值、命中率及闪避率提升15%(1回合)\n自身MP变动无效\n效果结束时，\n自身MP减少6","action_timing":18,"tlimit":0,"active_condition_set_id":1000662,"target_condition_set_id":1000001,"value_source_condition_set_id":0,"target_weapon_condition_id":0,"use_battle_animation":false,"battle_power_value_rate_percent":0,"trait_boost_condition_set_id":0,"active_condition":{"id":1000662,"trait_condition_set_id":1000662,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"7950","unit_size":"","tension":"SuperHigh,Supercharged","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0,"en_rate_gte_threshold":0,"en_value_lte_threshold":0,"en_value_gte_threshold":0,"use_hp_rate_lte_threshold":false,"attack_distance_gte_threshold":0,"attack_distance_lte_threshold":0,"turn_number":0,"is_in_chance_step":false,"is_in_one_on_one":false,"unit_ids":"","character_ids":"","character_tags_id":"","character_series_id":"","tags":null,"series":{"id":7950,"world_id":0,"name":"GUNDAM EXA","desc":"人类在生物学上的进化已然停滞，正逐步走向灭亡。\n为了扭转这场毁灭性的危机，寻求人类进化的关键，雷欧斯‧阿罗依来到太空站「土星引擎Ⅹ」。\n在领航员赛西亚‧艾维亚的引导下，雷欧斯潜行至「G高达」、「SEED」、「00」等各个高达世界。\n然而，同一时间，一名暗中监视著雷欧斯的男子「ex-（伊克斯）」也正在蠢蠢欲动……\n「ex-」口中的「极限高达」究竟是什么！？\n由Koichi Tokita、Tomohiro Chiba携手打造的高达漫画，将带来前所未见、震撼人心的高达世界。","icon":"series_7950","sort":25750,"schedule_id":2610209901,"scenario_stage_series_id":0,"scenario":null,"scenarios":null,"scenario_stages":null},"character_series":null,"character_tags":null},"target_condition":{"id":1000001,"trait_condition_set_id":1000001,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","